static const char *TAG="web";
static const char PAGE[] = R"HTML(<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NeedleMeter</title><style>body{font:16px system-ui;margin:24px;max-width:900px;color:#17212b}h1{margin-bottom:4px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.card{padding:14px;border:1px solid #d4d9df;border-radius:10px}.big{font-size:28px;font-weight:700}.ok{color:#087f3b}.bad{color:#b42318}button{padding:10px;margin:4px 4px 4px 0}label{display:block;margin:7px 0}input{float:right;width:130px}#msg{min-height:24px}</style><h1>NeedleMeter</h1><p id="msg"></p><div class="grid"><section class="card"><b>Последнее измерение</b><div class="big" id="length">—</div><div>Номинал: <span id="nominal"></span> mm</div><div>Отклонение: <span id="deviation"></span> mm</div><div>Допуск: ±<span id="tolerance"></span> mm</div><div class="big" id="result">—</div></section><section class="card"><div>Состояние: <b id="state"></b></div><div>Ошибка: <b id="error"></b></div><div>Игла: <span id="needle"></span></div><div>Контакт: <span id="contact"></span></div><div>STOP: <span id="stop"></span></div><div>Двигатель: <span id="motor"></span></div></section><section class="card"><div>После калибровки: <b id="since"></b></div><div>Всего: <b id="total"></b></div><div>Шагов измерения: <b id="steps"></b></div><div>Шагов калибровки: <b id="calsteps"></b></div><div>Калибровка: <b id="calvalid"></b></div></section></div><p><button onclick="cmd('measure')">Запустить измерение</button><button onclick="cmd('calibrate')">Запустить калибровку</button><button onclick="cmd('reset-stop')">Сбросить STOP</button><button onclick="cmd('reset-error')">Сбросить ошибку</button><button onclick="cmd('factory-reset')">Заводские настройки</button></p><h2>Настройки</h2><form id="cfg" class="grid"></form><p><button onclick="save();return false">Сохранить настройки</button></p><script>const fields=['nominal_length_mm','tolerance_mm','calibration_length_mm','mm_per_step','measurement_speed_steps_s','calibration_speed_steps_s','manual_speed_steps_s','max_measurement_steps','max_calibration_steps','measurement_timeout_ms','calibration_timeout_ms','measurement_sign','measure_dir_inverted','left_dir_inverted','disable_motor_when_idle','stop_manual_on_contact','debounce_ms'];let labels={nominal_length_mm:'Номинальная длина, mm',tolerance_mm:'Допуск ±, mm',calibration_length_mm:'Длина калибра, mm',mm_per_step:'mm/step',measurement_speed_steps_s:'Скорость измерения',calibration_speed_steps_s:'Скорость калибровки',manual_speed_steps_s:'Скорость JOG',max_measurement_steps:'Максимум шагов измерения',max_calibration_steps:'Максимум шагов калибровки',measurement_timeout_ms:'Timeout измерения, ms',calibration_timeout_ms:'Timeout калибровки, ms',measurement_sign:'Знак измерения (+1/-1)',measure_dir_inverted:'Инвертировать DIR измерения',left_dir_inverted:'Инвертировать DIR влево',disable_motor_when_idle:'Отключать мотор в IDLE',stop_manual_on_contact:'Останавливать JOG контактом',debounce_ms:'Debounce, ms'};function msg(x,bad=false){let e=document.querySelector('#msg');e.textContent=x;e.className=bad?'bad':'ok'}function put(s){for(let k of ['state','error'])document.querySelector('#'+k).textContent=s[k];for(let [id,v] of Object.entries({length:s.last_length_mm?.toFixed(3)||'—',nominal:s.nominal_length_mm,deviation:s.deviation_mm?.toFixed(3)||'—',tolerance:s.tolerance_mm,needle:s.needle_present?'обнаружена':'отсутствует',contact:s.contact?'замкнут':'разомкнут',stop:s.stop_active?'АКТИВЕН':'нормально',motor:s.motor_enabled?'включён':'выключен',since:s.measurements_since_calibration,total:s.total_measurements,steps:s.last_measurement_steps,calsteps:s.calibration_steps,calvalid:s.calibration_valid?'действительна':'нет'}))document.querySelector('#'+id).textContent=v;let r=document.querySelector('#result');r.textContent=s.result;r.className='big '+(s.result==='OK'?'ok':'bad')}async function status(){try{put(await (await fetch('/api/status')).json())}catch(e){msg('Нет связи с устройством',true)}}async function load(){let c=await(await fetch('/api/config')).json();let f=document.querySelector('#cfg');f.innerHTML='';for(let k of fields){let bool=typeof c[k]==='boolean';f.insertAdjacentHTML('beforeend',`<label>${labels[k]} <input id="${k}" type="${bool?'checkbox':'number'}" ${bool&&c[k]?'checked':''} value="${bool?'1':c[k]}" step="any"></label>`)} }async function cmd(x){let r=await fetch('/api/'+x,{method:'POST'});msg(r.ok?'Команда принята':'Команда отклонена',!r.ok)}async function save(){let x={};for(let k of fields){let e=document.querySelector('#'+k);x[k]=e.type==='checkbox'?e.checked:Number(e.value)}let r=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(x)});msg(r.ok?'Настройки сохранены':await r.text(),!r.ok)}load();status();setInterval(status,500);</script></html>)HTML";
static esp_err_t send_json(httpd_req_t *r, const char *body) { httpd_resp_set_type(r, HTTPD_TYPE_JSON); return httpd_resp_sendstr(r, body); }
static const char *result_name(const DeviceStats &s) { return std::strcmp(s.last_result, "OK") == 0 ? "OK" : std::strcmp(s.last_result, "TOO_SHORT") == 0 ? "TOO_SHORT" : std::strcmp(s.last_result, "TOO_LONG") == 0 ? "TOO_LONG" : "NONE"; }
static esp_err_t root(httpd_req_t*r){httpd_resp_set_type(r,"text/html; charset=utf-8");return httpd_resp_send(r,PAGE,HTTPD_RESP_USE_STRLEN);}
static esp_err_t status(httpd_req_t*r){auto*c=static_cast<MeasurementController*>(r->user_ctx);StatusSnapshot s;if(!c||!c->snapshot(s))return httpd_resp_send_err(r,HTTPD_500_INTERNAL_SERVER_ERROR,"Controller unavailable");char b[1024];int n=std::snprintf(b,sizeof(b),"{\"state\":\"%s\",\"error\":\"%s\",\"needle_present\":%s,\"contact\":%s,\"stop_active\":%s,\"motor_enabled\":%s,\"last_length_mm\":%.6f,\"nominal_length_mm\":%.6f,\"deviation_mm\":%.6f,\"tolerance_mm\":%.6f,\"result\":\"%s\",\"measurements_since_calibration\":%lu,\"total_measurements\":%lu,\"last_measurement_steps\":%lu,\"calibration_steps\":%lu,\"calibration_valid\":%s}",state_name(s.state),error_name(s.error),s.needle_present?"true":"false",s.contact?"true":"false",s.stop_active?"true":"false",s.motor_enabled?"true":"false",s.stats.last_measured_length,s.config.nominal_length_mm,s.stats.last_deviation,s.config.tolerance_mm,result_name(s.stats),static_cast<unsigned long>(s.stats.measurements_since_calibration),static_cast<unsigned long>(s.stats.total_measurements),static_cast<unsigned long>(s.stats.last_measurement_steps),static_cast<unsigned long>(s.stats.calibration_steps),s.stats.calibration_valid?"true":"false");return n<0||static_cast<size_t>(n)>=sizeof(b)?ESP_ERR_NO_MEM:send_json(r,b);}
static esp_err_t get_config(httpd_req_t*r){auto*c=static_cast<MeasurementController*>(r->user_ctx);StatusSnapshot s;if(!c||!c->snapshot(s))return httpd_resp_send_err(r,HTTPD_500_INTERNAL_SERVER_ERROR,"Controller unavailable");const DeviceConfig&x=s.config;char b[1024];int n=std::snprintf(b,sizeof(b),"{\"nominal_length_mm\":%.6f,\"tolerance_mm\":%.6f,\"calibration_length_mm\":%.6f,\"mm_per_step\":%.9f,\"measurement_speed_steps_s\":%lu,\"calibration_speed_steps_s\":%lu,\"manual_speed_steps_s\":%lu,\"max_measurement_steps\":%lu,\"max_calibration_steps\":%lu,\"measurement_timeout_ms\":%lu,\"calibration_timeout_ms\":%lu,\"measurement_sign\":%ld,\"measure_dir_inverted\":%s,\"left_dir_inverted\":%s,\"disable_motor_when_idle\":%s,\"stop_manual_on_contact\":%s,\"debounce_ms\":%lu}",x.nominal_length_mm,x.tolerance_mm,x.calibration_length_mm,x.mm_per_step,static_cast<unsigned long>(x.measurement_speed_steps_s),static_cast<unsigned long>(x.calibration_speed_steps_s),static_cast<unsigned long>(x.manual_speed_steps_s),static_cast<unsigned long>(x.max_measurement_steps),static_cast<unsigned long>(x.max_calibration_steps),static_cast<unsigned long>(x.measurement_timeout_ms),static_cast<unsigned long>(x.calibration_timeout_ms),static_cast<long>(x.measurement_sign),x.measure_dir_inverted?"true":"false",x.left_dir_inverted?"true":"false",x.disable_motor_when_idle?"true":"false",x.stop_manual_on_contact?"true":"false",static_cast<unsigned long>(x.debounce_ms));return n<0||static_cast<size_t>(n)>=sizeof(b)?ESP_ERR_NO_MEM:send_json(r,b);}
static const char *json_value(const char *body,const char *key){char needle[64];int n=std::snprintf(needle,sizeof(needle),"\"%s\"",key);if(n<0||static_cast<size_t>(n)>=sizeof(needle))return nullptr;const char*p=std::strstr(body,needle);if(!p)return nullptr;p+=n;while(std::isspace(static_cast<unsigned char>(*p)))++p;if(*p++!=':')return nullptr;while(std::isspace(static_cast<unsigned char>(*p)))++p;return p;}
static bool parse_number(const char *p,double&value){if(!p)return false;char*end=nullptr;value=std::strtod(p,&end);if(end==p||!std::isfinite(value))return false;while(std::isspace(static_cast<unsigned char>(*end)))++end;return *end==','||*end=='}'||*end==0;}
static bool optional_double(const char*b,const char*k,double&v){const char*p=json_value(b,k);if(!p)return true;double x;if(!parse_number(p,x))return false;v=x;return true;}
static bool optional_u32(const char*b,const char*k,uint32_t&v){const char*p=json_value(b,k);if(!p)return true;double x;if(!parse_number(p,x)||x<0||x>4294967295.0||std::floor(x)!=x)return false;v=static_cast<uint32_t>(x);return true;}
static bool optional_bool(const char*b,const char*k,bool&v){const char*p=json_value(b,k);if(!p)return true;const char*end=nullptr;if(std::strncmp(p,"true",4)==0){v=true;end=p+4;}else if(std::strncmp(p,"false",5)==0){v=false;end=p+5;}else return false;while(std::isspace(static_cast<unsigned char>(*end)))++end;return *end==','||*end=='}'||*end==0;}
static bool read_body(httpd_req_t*r,char*b,size_t capacity){if(r->content_len<=0||static_cast<size_t>(r->content_len)>=capacity)return false;int off=0,got;while(off<r->content_len){got=httpd_req_recv(r,b+off,r->content_len-off);if(got<=0)return false;off+=got;}b[off]=0;return true;}
static esp_err_t post_config(httpd_req_t*r){char b[2049];if(!read_body(r,b,sizeof(b)))return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Invalid body");auto*c=static_cast<MeasurementController*>(r->user_ctx);StatusSnapshot s;if(!c||!c->snapshot(s))return httpd_resp_send_err(r,HTTPD_500_INTERNAL_SERVER_ERROR,"Controller unavailable");DeviceConfig x=s.config;double sign=static_cast<double>(x.measurement_sign);bool valid=optional_double(b,"nominal_length_mm",x.nominal_length_mm)&&optional_double(b,"tolerance_mm",x.tolerance_mm)&&optional_double(b,"calibration_length_mm",x.calibration_length_mm)&&optional_double(b,"mm_per_step",x.mm_per_step)&&optional_u32(b,"measurement_speed_steps_s",x.measurement_speed_steps_s)&&optional_u32(b,"calibration_speed_steps_s",x.calibration_speed_steps_s)&&optional_u32(b,"manual_speed_steps_s",x.manual_speed_steps_s)&&optional_u32(b,"max_measurement_steps",x.max_measurement_steps)&&optional_u32(b,"max_calibration_steps",x.max_calibration_steps)&&optional_u32(b,"measurement_timeout_ms",x.measurement_timeout_ms)&&optional_u32(b,"calibration_timeout_ms",x.calibration_timeout_ms)&&optional_double(b,"measurement_sign",sign)&&optional_bool(b,"measure_dir_inverted",x.measure_dir_inverted)&&optional_bool(b,"left_dir_inverted",x.left_dir_inverted)&&optional_bool(b,"disable_motor_when_idle",x.disable_motor_when_idle)&&optional_bool(b,"stop_manual_on_contact",x.stop_manual_on_contact)&&optional_u32(b,"debounce_ms",x.debounce_ms);if(!valid||std::floor(sign)!=sign||sign<-2147483648.0||sign>2147483647.0)return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,"Invalid JSON value");x.measurement_sign=static_cast<int32_t>(sign);const char*why=nullptr;if(!c->update_config(x,&why))return httpd_resp_send_err(r,HTTPD_400_BAD_REQUEST,why?why:"Settings rejected");return send_json(r,"{\"ok\":true}");}
static esp_err_t command(httpd_req_t*r){auto*c=static_cast<MeasurementController*>(r->user_ctx);const char*u=r->uri;CommandType x=std::strstr(u,"measure")?CommandType::Measure:std::strstr(u,"calibrate")?CommandType::Calibrate:std::strstr(u,"reset-stop")?CommandType::ResetStop:std::strstr(u,"reset-error")?CommandType::ResetError:CommandType::FactoryReset;if(!c->enqueue(x)){httpd_resp_set_status(r,"503 Service Unavailable");return send_json(r,"{\"error\":\"Command queue full\"}");}return send_json(r,"{\"accepted\":true}");}
esp_err_t WebServer::start(MeasurementController*c){if(!c)return ESP_ERR_INVALID_ARG;if(server_){ESP_LOGW(TAG,"HTTP server is already running");return ESP_ERR_INVALID_STATE;}constexpr size_t handler_count=9;httpd_config_t cfg=HTTPD_DEFAULT_CONFIG();cfg.max_uri_handlers=12;httpd_handle_t s=nullptr;ESP_LOGI(TAG,"HTTP server starting...");esp_err_t err=httpd_start(&s,&cfg);if(err!=ESP_OK){ESP_LOGE(TAG,"HTTP server start failed: %s",esp_err_to_name(err));return err;}const httpd_uri_t uris[]={{.uri="/",.method=HTTP_GET,.handler=root,.user_ctx=c},{.uri="/api/status",.method=HTTP_GET,.handler=status,.user_ctx=c},{.uri="/api/config",.method=HTTP_GET,.handler=get_config,.user_ctx=c},{.uri="/api/config",.method=HTTP_POST,.handler=post_config,.user_ctx=c},{.uri="/api/measure",.method=HTTP_POST,.handler=command,.user_ctx=c},{.uri="/api/calibrate",.method=HTTP_POST,.handler=command,.user_ctx=c},{.uri="/api/reset-stop",.method=HTTP_POST,.handler=command,.user_ctx=c},{.uri="/api/reset-error",.method=HTTP_POST,.handler=command,.user_ctx=c},{.uri="/api/factory-reset",.method=HTTP_POST,.handler=command,.user_ctx=c}};static_assert(sizeof(uris)/sizeof(uris[0])==handler_count,"Update handler count");for(size_t i=0;i<handler_count;++i){err=httpd_register_uri_handler(s,&uris[i]);if(err!=ESP_OK){ESP_LOGE(TAG,"HTTP handler %u (%s) failed: %s",static_cast<unsigned>(i),uris[i].uri,esp_err_to_name(err));httpd_stop(s);return err;}}server_=s;ESP_LOGI(TAG,"HTTP handlers registered: %u",static_cast<unsigned>(handler_count));ESP_LOGI(TAG,"HTTP server started");return ESP_OK;}
